	,getPointIndexOffset: function(p,offset) {
		if(offset == null) {
			offset = 0;
		}
		var no = offset;
		var didBreak = false;
		var _g = 0;
		while(_g < 3) {
			var n = _g++;
			while(no < 0) no += 3;
			while(no > 2) no -= 3;
			var that = this.points[n];
			if(p.x == that.x && p.y == that.y) {
				didBreak = true;
				break;
			}
			++no;
		}
		if(!didBreak) {
			throw haxe_Exception.thrown("Triangle::Point not in triangle");
		}
		return no;
	}
